use xiom.io;

use xiom.string;
fn average(scores: Vec[Int]) -> Int {
  if scores.is_empty() { return 0; }
  let total: Int = 0;
  for score in scores {
    total = total + score;
  }
  return total / scores.len();
}

fn highest(scores: Vec[Int]) -> Option[Int] {
  if scores.is_empty() { return None; }
  let max: Int = 0;
  for score in scores {
    if score > max { max = score; }
  }
  return Some(max);
}

fn main() -> Int {
  let scores: Vec[Int] = Vec[Int].new();
  scores.push(85);
  scores.push(92);
  scores.push(78);
  scores.push(95);
  scores.push(88);

  io.println("Average: " + string.int_to_str(average(scores)));
  match highest(scores) {
    Some(h) -> io.println("Highest: " + string.int_to_str(h));
    None -> io.println("No scores");
  }
  return 0;
}
